MessageCenterAsyncWaiter::MessageCenterAsyncWaiter(
    MessageCenter* proxy) : proxy_(proxy) {}

MessageCenterAsyncWaiter::~MessageCenterAsyncWaiter() = default;

void MessageCenterAsyncWaiter::GetDisplayedNotifications(
    std::vector<std::string>* out_ids) {
  base::RunLoop loop;
  proxy_->GetDisplayedNotifications(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<std::string>* out_ids
,
             const std::vector<std::string>& ids) {*out_ids = std::move(ids);
            loop->Quit();
          },
          &loop,
          out_ids));
  loop.Run();
}

std::vector<std::string> MessageCenterAsyncWaiter::GetDisplayedNotifications(
    ) {
  std::vector<std::string> async_wait_result;
  GetDisplayedNotifications(&async_wait_result);
  return async_wait_result;
}




